class ReviewLog extends DataClass implements Insertable<ReviewLog> {
  final String id;
  final String cardStateId;
  final String? cardTemplateId;

  /// v2: unit key snapshot at review time.
  final String? unitKey;

  /// v1 legacy rating: 0=forgot 1=fuzzy 2=remembered.
  final int rating;

  /// v2 FSRS rating: 1=Again 2=Hard 3=Good 4=Easy.
  final int? ratingFsrs;

  /// v2: auto-graded correctness 0/1 (nullable for self-judged attempts).
  final int? correct;

  /// v2 judging mode: `auto` (strict char comparison) / `self`.
  final String? judgeMode;

  /// v2 presented form: mcq / mcq_multi / ordered_multi / fill / essay.
  final String? format;

  /// v2 answer time in ms.
  final int? msTaken;

  /// v9: did the user read the expected answer/solution after a failed recall?
  ///
  /// This is MindNet's `reviewed_solution` (`docs/IO_PROTOCOL.md` §2.3): the
  /// same wrong answer is two different events depending on it - a bare miss
  /// (`lapse`, S drops) or a learning event (`retrieval_failure_feedback`,
  /// whose S gain grows with [closeness]). NULL means "not asked or not
  /// applicable" (every right answer, and rows written before v9), never
  /// "false by default": the two paths must stay distinguishable after the
  /// fact instead of being silently flattened into one.
  final bool? reviewedSolution;

  /// v9: how close the failed recall was, in `(0, 1)`, when
  /// [reviewedSolution] is true.
  ///
  /// MindNet's `closeness = x_v / C_v` (`docs/MODEL_v2_MATH.md` §3): the
  /// stability gain of a failure-feedback event is multiplied by exactly this
  /// number, so it is stored verbatim rather than folded into a boolean.
  /// NULL whenever the event was not a failure-feedback one.
  final double? closeness;

  /// v11: the model's `R` for this card **at the moment of the review, before
  /// the grade existed**.
  ///
  /// This is what makes the calibration curve honest: a prediction recomputed
  /// after the fact from the post-review state would be grading the model on an
  /// answer it already knew (`docs/ASSESSMENT_DESIGN.md` §7 M6). NULL for every
  /// row written before v11 and for reviews where the advisor was unavailable -
  /// "no prediction" and "predicted 0.5" are different facts.
  final double? predictedR;
  final int reviewedAt;
  final int createdAt;
  const ReviewLog(
      {required this.id,
      required this.cardStateId,
      this.cardTemplateId,
      this.unitKey,
      required this.rating,
      this.ratingFsrs,
      this.correct,
      this.judgeMode,
      this.format,
      this.msTaken,
      this.reviewedSolution,
      this.closeness,
      this.predictedR,
      required this.reviewedAt,
      required this.createdAt});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['card_state_id'] = Variable<String>(cardStateId);
    if (!nullToAbsent || cardTemplateId != null) {
      map['card_template_id'] = Variable<String>(cardTemplateId);
    }
    if (!nullToAbsent || unitKey != null) {
      map['unit_key'] = Variable<String>(unitKey);
    }
    map['rating'] = Variable<int>(rating);
    if (!nullToAbsent || ratingFsrs != null) {
      map['rating_fsrs'] = Variable<int>(ratingFsrs);
    }
    if (!nullToAbsent || correct != null) {
      map['correct'] = Variable<int>(correct);
    }
    if (!nullToAbsent || judgeMode != null) {
      map['judge_mode'] = Variable<String>(judgeMode);
    }
    if (!nullToAbsent || format != null) {
      map['format'] = Variable<String>(format);
    }
    if (!nullToAbsent || msTaken != null) {
      map['ms_taken'] = Variable<int>(msTaken);
    }
    if (!nullToAbsent || reviewedSolution != null) {
      map['reviewed_solution'] = Variable<bool>(reviewedSolution);
    }
    if (!nullToAbsent || closeness != null) {
      map['closeness'] = Variable<double>(closeness);
    }
    if (!nullToAbsent || predictedR != null) {
      map['predicted_r'] = Variable<double>(predictedR);
    }
    map['reviewed_at'] = Variable<int>(reviewedAt);
    map['created_at'] = Variable<int>(createdAt);
    return map;
  }

  ReviewLogsCompanion toCompanion(bool nullToAbsent) {
    return ReviewLogsCompanion(
      id: Value(id),
      cardStateId: Value(cardStateId),
      cardTemplateId: cardTemplateId == null && nullToAbsent
          ? const Value.absent()
          : Value(cardTemplateId),
      unitKey: unitKey == null && nullToAbsent
          ? const Value.absent()
          : Value(unitKey),
      rating: Value(rating),
      ratingFsrs: ratingFsrs == null && nullToAbsent
          ? const Value.absent()
          : Value(ratingFsrs),
      correct: correct == null && nullToAbsent
          ? const Value.absent()
          : Value(correct),
      judgeMode: judgeMode == null && nullToAbsent
          ? const Value.absent()
          : Value(judgeMode),
      format:
