          : Value(msTaken),
      reviewedSolution: reviewedSolution == null && nullToAbsent
          ? const Value.absent()
          : Value(reviewedSolution),
      closeness: closeness == null && nullToAbsent
          ? const Value.absent()
          : Value(closeness),
      predictedR: predictedR == null && nullToAbsent
          ? const Value.absent()
          : Value(predictedR),
      reviewedAt: Value(reviewedAt),
      createdAt: Value(createdAt),
    );
  }

  factory ReviewLog.fromJson(Map<String, dynamic> json,
      {ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return ReviewLog(
      id: serializer.fromJson<String>(json['id']),
      cardStateId: serializer.fromJson<String>(json['cardStateId']),
      cardTemplateId: serializer.fromJson<String?>(json['cardTemplateId']),
      unitKey: serializer.fromJson<String?>(json['unitKey']),
