class Question extends DataClass implements Insertable<Question> {
  final String id;

  /// 人可读的题目编号（v24，轮次一百二十一）：**跨学科一个序列**，1 起分配，
  /// 显示成 `TR-00001`（见 `domain/services/questions/question_number.dart`）。
  ///
  /// 为什么不拿 [id] 当编号：id 是 `q-<uuid>`，给人看太长、背不住、写不上纸。
  /// 编号要短、要稳、要能在错题本上抄。可空是为了兼容三件事：老文件升级
  /// （迁移里回填）、v23 及更早的 `.tfpkg` 包（导入后
  /// `AppDatabase.backfillQuestionSerialNumbers` 补）、以及 append 导入。
  /// NULL 的含义是"还没编号"，界面上显示占位，不是 0 号。
  final int? serialNo;

  /// 题名（v30，轮次一百三十九）：用户自己起的名字，或域层自动生成的短名。
  ///
  /// 为什么不从题干现算：题库总览要按名字扫读、还要能重命名——题干前 20 字
  /// 常常是同一种题型的相同开头（"已知函数 f(x)…"），扫读时全是重影。
  /// 列存下来才有“稳定、可改、可去重”的语义；自动生成只是**填空**，
  /// 填过之后用户改过就不再自动覆盖。可空表示“还没名字”，界面回落题干摘要。
  /// 长度与合法性由域层纯逻辑 `question_title_suggestion.dart` 把关，
  /// 仓库只 trim、空串写 NULL（与 `source_url` 同一契约），不在这里做长度截断。
  final String? title;

  /// 题干（纯文本；公式保留 LaTeX 原样）。
  final String stem;

  /// 参考答案。可空：收题时可以只存题干，答案后补。
  final String? answer;

  /// 解析文本。AI 解题产出的**思维链**另存 `reasoning_chains`，不挤在这一列。
  final String? solution;

  /// 学科，例如 `physics` / `chinese`。自由字符串，界面用标签树展示。
  final String subjectKey;

  /// `single_choice` / `multi_choice` / `fill_blank` / `solution` / `open`。
  final String questionType;

  /// 来源分级（决定排序权重与去重保留优先级）：`gaokao` 高考真题 /
  /// `provincial_diagnostic` 强省强市诊断 / `elite_school` 名校测试 /
  /// `school` 学校题 / `personal` 自建 / `unknown` 未标注。
  final String sourceLevel;

  /// 人可读来源，例如"2024 湖南师大附中月考"。
  final String sourceLabel;
  final int? year;
  final String? region;

  /// 题目在外部站点（现在只有组卷网）的来源页链接（v26，轮次一百二十九）。
  ///
  /// 为什么要存 URL 而不只存人读的来源文字：定点找题是「链接去、题回来」，
  /// 回来以后人还得能点回去核对原题与答案图；`sourceLabel` 写的是出处文字
  /// （"2024 湖南师大附中月考"），它可能抄错，URL 是唯一可复查的锚点。
  /// 可空：手写收题、拍照识别、自建题都没有外部来源。
  final String? sourceUrl;

  /// 组卷网的题目 id（URL 里 `<bankid>q<questionid>.html` 的 questionid）。
  ///
  /// 留着它就能**重建**详情页/答案页链接，也能按 qid 去重——比题干指纹更硬
  /// （同一道题换排版、题干少一个字都可能换指纹）。可空：非组卷网来源。
  final String? zujuanQuestionId;

  /// 组卷网的学科 bankid（URL 里 `<bankid>q<questionid>.html` 的 bankid）。
  ///
  /// bankid 决定站点按哪个学科解释链接，缺了它拼出来的链接会落到别的学科
  /// （站点按 bankId 静默过滤，错学科 0 条）。所以宁可两列都存、也不从
  /// questionid 猜。可空同上。
  final String? zujuanBankId;

  /// 难度 1–10，可空。优先写认知模型的难度先验，否则写 AI 估计。
  final double? difficulty;

  /// 上面那个难度是谁给的：`prior` / `ai` / `manual`。没有难度时 NULL。
  final String? difficultySource;

  /// 题干指纹（去空白 + 标点归一的 FNV-1a 64 位十六进制，纯 Dart 实现）。
  /// 只挡"完全同一道题"；近似重复留给后续按考点链找相似题。
  final String stemFingerprint;

  /// 易错点/常见错因（加工产物，可空）。
  final String? trapNote;

  /// `raw` 刚收进来 / `structured` 已结构化 / `processed` 已拆链并标注错因。
  final String state;

  /// AI 预评分 0–1（来源等级、年份、考点覆盖、题干完整度）。不删低分题，只压后。
  final double? aiQuality;

  /// `aiQuality` 的理由，一行中文。
  final String? aiQualityNote;

  /// `manual` / `ai_scan`（拍照或文本扫描）/ `furnace`（App 内自建）。
  final String origin;
  final int createdAt;
  final int updatedAt;
  const Question(
      {required this.id,
      this.serialNo,
      this.title,
      required this.stem,
      this.answer,
      this.solution,
      required this.subjectKey,
      required this.questionType,
      required this.sourceLevel,
      required this.sourceLabel,
      this.year,
      this.region,
      this.sourceUrl,
      this.zujuanQuestionId,
      this.zujuanBankId,
      this.difficulty,
      this.difficultySource,
      required this.stemFingerprint,
      this.trapNote,
      required this.state,
      this.aiQuality,
      this.aiQualityNote,
      required this.origin,
      required this.createdAt,
      required this.updatedAt});
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    if (!nullToAbsent || serialNo != null) {
      map['serial_no'] = Variable<int>(serialNo);
    }
    if (!nullToAbsent || title != null) {
      map['title'] = Variable<String>(title);
    }
    map['stem'] = Variable<String>(stem);
    if (!nullToAbsent || answer != null) {
      map['answer'] = Variable<String>(answer);
    }
    if (!nullToAbsent || solution != null) {
      map['solution'] = Variable<String>(solution);
    }
    map['subject_key'] = Variable<String>(subjectKey);
    map['question_type'] = Variable<String>(questionType);
    map['source_level'] = Variable<String>(sourceLevel);
    map['source_label'] = Variable<String>(sourceLabel);
    if (!nullToAbsent || year != null) {
      map['year'] = Variable<int>(year);
    }
    if (!nullToAbsent || region != null) {
      map['region'] = Variable<String>(region);
    }
    if (!nullToAbsent || sourceUrl != null) {
      map['source_url'] = Variable<String>(sourceUrl);
    }
    if (!nullToAbsent || zujuanQuestionId != null) {
      map['zujuan_question_id'] = Variable<String>(zujuanQuestionId);
    }
    if (!nullToAbsent || zujuanBankId != null) {
      map['zujuan_bank_id'] = Variable<String>(zujuanBankId);
    }
    if (!nullToAbsent || difficulty != null) {
      map['difficulty'] = Variable<double>(difficulty);
    }
    if (!nullToAbsent || difficultySource != null) {
      map['difficulty_source'] = Variable<String>(difficultySource);
    }
    map['stem_fingerprint'] = Variable<String>(stemFingerprint);
    if (!nullToAbsent || trapNote != null) {
      map['trap_note'] = Variable<String>(trapNote);
    }
    map['state'] = Variable<String>(state);
    if (!nullToAbsent || aiQuality != null) {
      map['ai_quality'] = Variable<double>(aiQuality);
    }
    if (!nullToAbsent || aiQualityNote != null) {
      map['ai_quality_note'] = Variable<String>(aiQualityNote);
    }
    map['origin'] = Variable<String>(origin);
    map['created_at'] = Variable<int>(createdAt);
    map['updated_at'] = Variable<int>(updatedAt);
    return map;
  }

